//! Input commitments v3 (`SHA256_N32_JCS_V3`).
//!
//! ```text
//! input_commitment = hex(SHA-256("VCAV-INPUT-COMMIT-V3:" || nonce[32] || JCS_v3(context)))
//! ```
//!
//! The 32-byte nonce is generated by the submitting client, sent to the relay
//! as `commitment_nonce` (64 lowercase hex characters) and never written to
//! the receipt. See `docs/receipt-v3.md`, section 5.

use serde_json::Value;
use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;
use thiserror::Error;

use crate::jcs::{canonicalize_v3, JcsError};

/// Domain separator for v3 input commitments.
pub const INPUT_COMMIT_DOMAIN_PREFIX_V3: &str = "VCAV-INPUT-COMMIT-V3:";

/// Scheme identifier written to each v3 input commitment entry.
pub const INPUT_COMMITMENT_SCHEME_V3: &str = "SHA256_N32_JCS_V3";

/// Nonce length in bytes.
pub const COMMITMENT_NONCE_LEN: usize = 32;

/// Errors from input commitment computation or checking.
#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum CommitmentError {
    /// The nonce is not exactly 64 lowercase hex characters.
    #[error("commitment nonce must be 64 lowercase hex characters (32 bytes)")]
    InvalidNonce,

    /// The expected commitment is not 64 lowercase hex characters.
    #[error("input commitment must be 64 lowercase hex characters")]
    InvalidCommitment,

    /// The context could not be canonicalised.
    #[error("context canonicalization failed: {0}")]
    Canonicalization(#[from] JcsError),
}

/// Parse a wire-format commitment nonce (64 lowercase hex characters).
pub fn parse_commitment_nonce(
    nonce_hex: &str,
) -> Result<[u8; COMMITMENT_NONCE_LEN], CommitmentError> {
    if !is_lower_hex(nonce_hex, COMMITMENT_NONCE_LEN * 2) {
        return Err(CommitmentError::InvalidNonce);
    }
    let bytes = hex::decode(nonce_hex).map_err(|_| CommitmentError::InvalidNonce)?;
    bytes.try_into().map_err(|_| CommitmentError::InvalidNonce)
}

/// Compute the v3 input commitment (lowercase hex) for `context` under `nonce`.
pub fn compute_input_commitment_v3(
    nonce: &[u8; COMMITMENT_NONCE_LEN],
    context: &Value,
) -> Result<String, CommitmentError> {
    let canonical = canonicalize_v3(context)?;
    let mut hasher = Sha256::new();
    hasher.update(INPUT_COMMIT_DOMAIN_PREFIX_V3.as_bytes());
    hasher.update(nonce);
    hasher.update(canonical.as_bytes());
    Ok(hex::encode(hasher.finalize()))
}

/// Check that `expected_hex` is the v3 commitment to `context` under `nonce`.
///
/// Returns `Ok(true)` on a match and `Ok(false)` on a mismatch. The digests
/// are compared in constant time.
pub fn verify_input_commitment_v3(
    nonce: &[u8; COMMITMENT_NONCE_LEN],
    context: &Value,
    expected_hex: &str,
) -> Result<bool, CommitmentError> {
    if !is_lower_hex(expected_hex, 64) {
        return Err(CommitmentError::InvalidCommitment);
    }
    let expected = hex::decode(expected_hex).map_err(|_| CommitmentError::InvalidCommitment)?;
    let computed = compute_input_commitment_v3(nonce, context)?;
    let computed = hex::decode(computed).map_err(|_| CommitmentError::InvalidCommitment)?;
    Ok(bool::from(computed.ct_eq(&expected)))
}

pub(crate) fn is_lower_hex(s: &str, len: usize) -> bool {
    s.len() == len && s.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    const NONCE: [u8; 32] = [0x11; 32];

    #[test]
    fn commitment_matches_manual_construction() {
        let context = json!({"b": 2, "a": "x"});
        let mut message = b"VCAV-INPUT-COMMIT-V3:".to_vec();
        message.extend_from_slice(&NONCE);
        message.extend_from_slice(br#"{"a":"x","b":2}"#);
        let expected = hex::encode(Sha256::digest(&message));
        assert_eq!(
            compute_input_commitment_v3(&NONCE, &context).unwrap(),
            expected
        );
    }

    #[test]
    fn wrong_nonce_fails_verification() {
        let context = json!({"salary": 90000});
        let commitment = compute_input_commitment_v3(&NONCE, &context).unwrap();
        assert!(verify_input_commitment_v3(&NONCE, &context, &commitment).unwrap());
        let mut other = NONCE;
        other[31] ^= 1;
        assert!(!verify_input_commitment_v3(&other, &context, &commitment).unwrap());
    }

    #[test]
    fn wrong_context_fails_verification() {
        let commitment = compute_input_commitment_v3(&NONCE, &json!({"salary": 90000})).unwrap();
        assert!(
            !verify_input_commitment_v3(&NONCE, &json!({"salary": 90001}), &commitment).unwrap()
        );
    }

    #[test]
    fn commitment_differs_from_unsalted_hash() {
        let context = json!({"salary": 90000});
        let unsalted = crate::jcs::hash_v3(&context).unwrap();
        assert_ne!(
            compute_input_commitment_v3(&NONCE, &context).unwrap(),
            unsalted
        );
    }

    #[test]
    fn nonce_parsing_is_strict() {
        assert_eq!(
            parse_commitment_nonce(&"ab".repeat(32)).unwrap(),
            [0xab; 32]
        );
        for bad in [
            "AB".repeat(32),
            "ab".repeat(31),
            "ab".repeat(33),
            format!("{}zz", "ab".repeat(31)),
            String::new(),
        ] {
            assert_eq!(
                parse_commitment_nonce(&bad),
                Err(CommitmentError::InvalidNonce)
            );
        }
    }

    #[test]
    fn rejects_out_of_range_context() {
        assert!(matches!(
            compute_input_commitment_v3(&NONCE, &json!({"n": 9007199254740992u64})),
            Err(CommitmentError::Canonicalization(
                JcsError::NumberOutOfRange { .. }
            ))
        ));
    }

    #[test]
    fn rejects_malformed_expected_commitment() {
        let context = json!({});
        let c = compute_input_commitment_v3(&NONCE, &context).unwrap();
        assert_eq!(
            verify_input_commitment_v3(&NONCE, &context, &c.to_uppercase()),
            Err(CommitmentError::InvalidCommitment)
        );
    }
}
